mapper.select:
SELECT
    (
        SELECT COUNT(DISTINCT user_id)
        FROM growth_journey_event
        WHERE event_type = 'PRIMARY_ACTION_SHOWN'
          AND create_time >= #{periodStart}
          AND create_time < #{periodEnd}
    ) AS primaryActionShownUsers,
    (
        SELECT COUNT(DISTINCT started.user_id)
        FROM growth_journey_event started
        WHERE started.event_type = 'PRIMARY_ACTION_STARTED'
          AND started.create_time >= #{periodStart}
          AND started.create_time < #{periodEnd}
          AND EXISTS (
              SELECT 1
              FROM growth_journey_event shown
              WHERE shown.user_id = started.user_id
                AND shown.tracking_id = started.tracking_id
                AND shown.event_type = 'PRIMARY_ACTION_SHOWN'
                AND shown.create_time >= #{periodStart}
                AND shown.create_time < #{periodEnd}
          )
    ) AS primaryActionStartedUsers,
    (
        SELECT COUNT(DISTINCT user_id)
        FROM growth_evidence
        WHERE quality_level = 'VERIFIED'
          AND observed_at >= #{periodStart}
          AND observed_at < #{periodEnd}
          AND (valid_to IS NULL OR valid_to > #{periodStart})
    ) AS verifiedGrowthUsers,
    (
        SELECT COUNT(*)
        FROM growth_coach_action_run
        WHERE action_id = 'growth.plan.adjust'
          AND created_at >= #{periodStart}
          AND created_at < #{periodEnd}
    ) AS planPreviewCount,
    (
        SELECT COUNT(*)
        FROM growth_coach_action_run
        WHERE action_id = 'growth.plan.adjust'
          AND status = 'EXECUTED'
          AND created_at >= #{periodStart}
          AND created_at < #{periodEnd}
    ) AS planExecutedCount,
    (
        SELECT COUNT(DISTINCT user_id)
        FROM career_application_record
        WHERE deleted = 0
          AND update_time >= #{periodStart}
          AND update_time < #{periodEnd}
    ) AS careerApplicationProgressUsers
